      "mobileSvg": "<svg class=\"course-diagram-svg mnu108-post-diagram\" viewBox=\"0 0 360 519.0500000000001\" width=\"100%\" role=\"img\" aria-labelledby=\"MNU108-13-12-4-m-t MNU108-13-12-4-m-d\" xmlns=\"http://www.w3.org/2000/svg\"><title id=\"MNU108-13-12-4-m-t\">Herzberg: dua area yang berbeda</title><desc id=\"MNU108-13-12-4-m-d\">Herzberg: dua area yang berbeda. Area dissatisfaction: hygiene; Area satisfaction: motivators</desc><defs><marker id=\"MNU108-13-12-4-m-arrow\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path class=\"svg-title\" d=\"M0 0 L10 5 L0 10 Z\"/></marker></defs><rect class=\"svg-bg\" width=\"360\" height=\"519.0500000000001\" rx=\"12\"/><rect class=\"svg-card\" x=\"20\" y=\"24\" width=\"153\" height=\"345.80000000000007\" rx=\"10\" stroke-width=\"1.5\"/><text class=\"svg-title\" x=\"34\" y=\"48\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">Area</tspan><tspan x=\"34\" dy=\"21.6\">dissatisfaction:</tspan><tspan x=\"34\" dy=\"21.6\">hygiene</tspan></text><text class=\"svg-text\" x=\"34\" y=\"122.80000000000001\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">Working</tspan></text><text class=\"svg-text\" x=\"34\" y=\"143.05\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">conditions;</tspan></text><text class=\"svg-text\" x=\"34\" y=\"163.3\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">pay/security</tspan></text><text class=\"svg-text\" x=\"34\" y=\"183.55\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">Company</tspan></text><text class=\"svg-text\" x=\"34\" y=\"203.8\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">policies;</tspan></text><text class=\"svg-text\" x=\"34\" y=\"224.05\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">supervisors;</tspan></text><text class=\"svg-text\" x=\"34\" y=\"244.3\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">relationships</tspan></text><text class=\"svg-text\" x=\"34\" y=\"264.55\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">Buruk →</tspan></text><text class=\"svg-text\" x=\"34\" y=\"284.8\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">dissatisfied;</tspan></text><text class=\"svg-text\" x=\"34\" y=\"305.05\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">memadai →</tspan></text><text class=\"svg-text\" x=\"34\" y=\"325.3\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">berkurang</tspan></text><text class=\"svg-text\" x=\"34\" y=\"345.55000000000007\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"34\" dy=\"0\">keluhan</tspan></text><rect class=\"svg-card\" x=\"187\" y=\"24\" width=\"153\" height=\"285.05\" rx=\"10\" stroke-width=\"1.5\"/><text class=\"svg-title\" x=\"201\" y=\"48\" font-size=\"16\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">Area</tspan><tspan x=\"201\" dy=\"21.6\">satisfaction:</tspan><tspan x=\"201\" dy=\"21.6\">motivators</tspan></text><text class=\"svg-text\" x=\"201\" y=\"122.80000000000001\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">Achievement;</tspan></text><text class=\"svg-text\" x=\"201\" y=\"143.05\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">recognition;</tspan></text><text class=\"svg-text\" x=\"201\" y=\"163.3\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">responsibility</tspan></text><text class=\"svg-text\" x=\"201\" y=\"183.55\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">Work itself;</tspan></text><text class=\"svg-text\" x=\"201\" y=\"203.8\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">personal</tspan></text><text class=\"svg-text\" x=\"201\" y=\"224.05\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">growth</tspan></text><text class=\"svg-text\" x=\"201\" y=\"244.3\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">Hadir →</tspan></text><text class=\"svg-text\" x=\"201\" y=\"264.55\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">satisfaction</tspan></text><text class=\"svg-text\" x=\"201\" y=\"284.8\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"201\" dy=\"0\">lebih tinggi</tspan></text><text class=\"svg-text\" x=\"20\" y=\"398.80000000000007\" font-size=\"15\" text-anchor=\"start\"><tspan x=\"20\" dy=\"0\">Neutral: neither satisfied nor</tspan><tspan x=\"20\" dy=\"20.25\">dissatisfied. Dua faktor tidak</tspan><tspan x=\"20\" dy=\"20.25\">diperlakukan sebagai satu garis</tspan><tspan x=\"20\" dy=\"20.25\">“gaji rendah → motivasi rendah”</tspan><tspan x=\"20\" dy=\"20.25\">untuk semua konteks.</tspan></text></svg>",
